define([
  'vb/action/actionChain',
  'vb/action/actions',
  'vb/action/actionUtils',
], (
  ActionChain,
  Actions,
  ActionUtils
) => {
  'use strict';

  class saveAssignmentChain extends ActionChain {

    /**
     * @param {Object} context
     */
    async run(context) {
      const { $flow, $application, $constants, $variables } = context;

      const tracker = document.getElementById('assignmentForm');
      if (tracker.valid !== 'valid') {
        tracker.showMessages();
        tracker.focusOn('@firstInvalidShown');
        return;
      }

      const patchResult = await Actions.callRest(context, {
        endpoint: '<serviceId>/<patchAssignmentEndpointId>',
        uriParams: {
          workersUniqID: $variables.workerKey,
          PeriodOfServiceId: $variables.periodOfServiceId,
          assignmentsUniqID: $variables.assignmentKey,
        },
        headers: {
          'Effective-Of': 'RangeMode=UPDATE;RangeStartDate=' + $variables.effectiveDate,
        },
        body: {
          DepartmentName: $variables.departmentName,
        },
      });

      if (!patchResult.ok) {
        await Actions.fireNotificationEvent(context, {
          summary: 'Assignment not saved',
          message: 'HTTP ' + patchResult.status + ' ' + patchResult.statusText,
          type: 'error',
          displayMode: 'persist',
        });
        return;
      }

      await Actions.fireNotificationEvent(context, {
        summary: 'Assignment updated from ' + $variables.effectiveDate,
        type: 'confirmation',
        displayMode: 'transient',
      });
    }
  }

  return saveAssignmentChain;
});

