define([
  'vb/action/actionChain',
  'vb/action/actions',
  'vb/action/actionUtils',
], (
  ActionChain,
  Actions,
  ActionUtils
) => {
  'use strict';

  class approveTaskChain extends ActionChain {

    /**
     * @param {Object} context
     * @param {Object} params
     * @param {number} params.taskNumber
     */
    async run(context, { taskNumber }) {
      const { $flow, $application, $constants, $variables } = context;

      const approveResult = await Actions.callRest(context, {
        endpoint: '<tasksServiceId>/<putTaskEndpointId>',
        uriParams: {
          id: taskNumber,
        },
        body: {
          action: { id: 'APPROVE' },
        },
      });

      if (!approveResult.ok) {
        await Actions.fireNotificationEvent(context, {
          summary: 'Approval failed',
          message: 'HTTP ' + approveResult.status,
          type: 'error',
          displayMode: 'persist',
        });
        return;
      }

      await Actions.fireDataProviderEvent(context, {
        target: $variables.tasksSDP,
        refresh: null,
      });
    }
  }

  return approveTaskChain;
});
